command:
$ErrorActionPreference="Stop"
$repo="C:\dev\flyExplorer"
$main="df8b172f605ada11ff3b9df3c466d9df8134aa37"
$candidate="dbec1433b4abe184ad9fb3c48ad0a897c7e71739"
$branch="work/verification-infra-hardening-20261005"
Set-Location -LiteralPath $repo
& git fetch origin main $branch --no-tags --prune
if($LASTEXITCODE -ne 0){throw "fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne $main){throw "main moved"}
if((& git rev-parse ("refs/remotes/origin/"+$branch)).Trim() -ne $candidate){throw "candidate moved"}
$temp=Join-Path $env:RUNNER_TEMP ("verification-hardening-"+$env:GITHUB_RUN_ID)
if(Test-Path -LiteralPath $temp){Remove-Item -LiteralPath $temp -Recurse -Force}
try{
  & git worktree add --detach $temp $candidate
  if($LASTEXITCODE -ne 0){throw "candidate worktree failed"}
  $env:PYTHONIOENCODING="utf-8"
  $changed=@(& git -C $temp diff --name-only ($main+".."+$candidate))
  $python=@($changed | Where-Object { $_ -match '\.py$' } | ForEach-Object { Join-Path $temp $_ })
  & python -X utf8 (Join-Path $temp "tools\winui\check_python_static.py") @python
  if($LASTEXITCODE -ne 0){throw "changed Python static check failed"}
  & python -X utf8 (Join-Path $temp "tools\winui\run_checks.py") harness
  if($LASTEXITCODE -ne 0){throw "harness suite failed"}
  & python -X utf8 (Join-Path $temp "tools\winui\run_checks.py") infra
  if($LASTEXITCODE -ne 0){throw "infra suite failed"}
  & git -C $temp diff --check ($main+".."+$candidate)
  if($LASTEXITCODE -ne 0){throw "candidate diff check failed"}
  Write-Host "VERIFICATION_HARDENING_PREMERGE_PASS"
}finally{
  Set-Location -LiteralPath $repo
  if(Test-Path -LiteralPath $temp){& git worktree remove --force $temp}
  & git worktree prune
}
